using OptimizeAll.Domain.Website;

namespace OptimizeAll.Api.Modules.Website.Seed;

internal sealed record PackageSeed(
    string Name, string Description, decimal? Price, PackageBillingPeriod Period, decimal? SetupFee, bool Popular, string[] Features);

internal sealed record ServiceSeed(
    string Slug, string Name, string Icon, string Tagline, string HeroBody, string Overview, string[] Problems, string[] Deliverables,
    string[] Tools, string[] Kpis, (string Q, string A)[] Faqs, PackageSeed[] Packages, string[]? Related = null, string? CtaLabel = null,
    string? CtaUrl = null, bool Featured = false);

internal sealed record CategorySeed(string Slug, string Name, string Icon, string Description, (string Title, string Text)[] Process, ServiceSeed[] Services);

/// <summary>
/// The agency's baseline service catalog: nine service lines and their services, with real, publishable copy and
/// starting packages. Prices are list prices in USD that the agency should review before launch; everything can be edited
/// in the CMS afterwards (the seed never overwrites existing rows).
