    private static PackageSeed[] Tiers(decimal starter, decimal growth, string[] starterFeatures, string[] growthFeatures, string[] scaleFeatures,
        decimal? setup = null, PackageBillingPeriod period = PackageBillingPeriod.Monthly, decimal? scale = null) => new[]
    {
        new PackageSeed("Starter", "For businesses laying the foundations.", starter, period, setup, false, starterFeatures),
        new PackageSeed("Growth", "Our most chosen plan for steady, compounding growth.", growth, period, setup, true, growthFeatures),
        new PackageSeed("Scale", "For ambitious teams that need senior strategy and more output.", scale, period, scale is null ? null : setup, false, scaleFeatures),
    };

    private static PackageSeed[] Projects(decimal starter, decimal growth, string[] starterFeatures, string[] growthFeatures, string[] scaleFeatures) =>
        Tiers(starter, growth, starterFeatures, growthFeatures, scaleFeatures, null, PackageBillingPeriod.OneTime);

